class IntakeTest {
  static final double DELTA = 1e-2;                  // float compare tolerance
  Intake intake;
  PWMMotorControllerSim simMotor;
  DoubleSolenoidSim simPiston;

  @BeforeEach
  void setup() {
    assert HAL.initialize(500, 0);                   // REQUIRED before any device
    intake = new Intake();
    simMotor = new PWMMotorControllerSim(IntakeConstants.kMotorPort);
    simPiston = new DoubleSolenoidSim(PneumaticsModuleType.CTRE_PCM,
        IntakeConstants.kPistonFwdChannel, IntakeConstants.kPistonRevChannel);
  }

  @AfterEach
  void shutdown() throws Exception { intake.close(); }   // Intake implements AutoCloseable

  @Test void worksWhenOpen() {
    intake.deploy(); intake.activate(0.5);
    assertEquals(0.5, simMotor.getThrottle(), DELTA);
  }
  @Test void retractTest() {
    intake.retract();
    assertEquals(DoubleSolenoid.Value.REVERSE, simPiston.get());
  }
}

