@Test void elevatorReachesSetpoint() {
  elevator.setGoal(Meters.of(1.0));
  for (int i = 0; i < 200; i++) {          // 200 * 20ms = 4 simulated seconds
    elevator.periodic();
    elevator.simulationPeriodic();          // NOTHING calls this for you in a unit test
    CommandScheduler.getInstance().run();   // ditto
    SimHooks.stepTiming(0.02);
  }
  assertEquals(1.0, elevator.getHeightMeters(), 0.02);
}
