private final SysIdRoutine routine = new SysIdRoutine(
    new SysIdRoutine.Config(),   // defaults: 1 V/s ramp, 7 V step; also takes
                                 // a timeout and a state-callback
    new SysIdRoutine.Mechanism(
        volts -> motor.setVoltage(volts.in(Volts)),
        log -> log.motor("elevator")
                  .voltage(appliedVolts)
                  .linearPosition(position)
                  .linearVelocity(velocity),
        this));

public Command sysIdQuasistatic(SysIdRoutine.Direction dir) { return routine.quasistatic(dir); }
public Command sysIdDynamic(SysIdRoutine.Direction dir)     { return routine.dynamic(dir); }

// Constructors: Alert(String text, AlertType type)
