private final Alert canBusAlert   = new Alert("Health", "CAN bus utilization high", kWarning);
private final Alert brownoutAlert = new Alert("Health", "Brownout detected", kError);
private final Alert encoderAlert  = new Alert("Health", "Arm encoder not moving", kError);

public void periodic() {
  var can = RobotController.getCANStatus();
  canBusAlert.set(can.percentBusUtilization > 0.8);
  brownoutAlert.set(RobotController.isBrownedOut());
  encoderAlert.set(Math.abs(appliedVolts) > 3.0 && Math.abs(velocity) < 0.01);
  motorMissingAlert.set(!talon.isConnected());          // Phoenix 6
}
